const viewer = (window.viewer = new Cesium.Viewer('cesiumContainer', {
  baseLayer: new Cesium.ImageryLayer(
    new Cesium.OpenStreetMapImageryProvider({
      url: 'https://tile.openstreetmap.org/',
      maximumLevel: 18,
    })
  ),
  baseLayerPicker: false,
  navigationHelpButton: false,
  animation: false,
  timeline: false,
  geocoder: false,
  homeButton: false,
  sceneModePicker: false,
  fullscreenButton: false,
  infoBox: false,
  selectionIndicator: false,
}));

viewer.scene.globe.enableLighting = false;

// Tight bounding rectangle around the Hawaiian Islands
const hawaiiRectangle = Cesium.Rectangle.fromDegrees(-161.0, 18.5, -154.0, 22.5);

// Regional UrlTemplateImageryProvider constrained to Hawaii.
// The provider itself is given the same rectangle so it never requests
// tiles outside the islands, and minimumTerrainLevel / maximumTerrainLevel
// on the ImageryLayer limit rendering to a deliberate zoom window.
const hawaiiProvider = new Cesium.UrlTemplateImageryProvider({
  url: 'https://tile.openstreetmap.org/{z}/{x}/{y}.png',
  credit: 'OpenStreetMap contributors',
  rectangle: hawaiiRectangle,
  minimumLevel: 2,
  maximumLevel: 16,
});

const hawaiiLayer = new Cesium.ImageryLayer(hawaiiProvider, {
  rectangle: hawaiiRectangle,
  maximumTerrainLevel: 14,  // do not render above this detail level (too zoomed-in)
});

hawaiiLayer.alpha = 0.8;
hawaiiLayer.brightness = 1.2;
hawaiiLayer.contrast = 1.25;
viewer.imageryLayers.add(hawaiiLayer);

viewer.entities.add({
  name: 'Regional imagery provider bounds',
  rectangle: {
    coordinates: hawaiiRectangle,
    fill: false,
    outline: true,
    outlineColor: Cesium.Color.RED,
    outlineWidth: 4,
  },
});

// Frame the camera on the Hawaiian Islands at a regional altitude.
viewer.camera.setView({
  destination: Cesium.Rectangle.fromDegrees(-162.0, 18.0, -153.5, 23.2),
  orientation: {
    heading: Cesium.Math.toRadians(0),
    pitch: Cesium.Math.toRadians(-90),
    roll: 0.0,
  },
});
